#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop("Usage: Rscript scripts/local/ytab_validate_one_sample_app_mapping.R <project.yaml> <sample>",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");config<-normalizePath(args[[1]],winslash="/");sample<-args[[2]];project_root<-dirname(dirname(config));out<-file.path(project_root,"mapfastq",sample);bam<-file.path(out,paste0(sample,".sorted.bam"));bai<-paste0(bam,".bai");stats<-file.path(out,paste0(sample,".mapping_stats.csv"));if(file.exists(bam))stop("Selected sample already has a BAM; refusing to use --force.",call.=FALSE)
app_env<-new.env(parent=.GlobalEnv);source(file.path(root,"app/shiny/app.R"),local=app_env);observed<-new.env(parent=emptyenv());observed$current<-FALSE;observed$running<-FALSE;observed$logs<-FALSE
shiny::testServer(app_env$server,{session$setInputs(project_selector=config);session$setInputs(open_project=1);session$flushReact();do.call(session$setInputs,setNames(list(sample),"preprocessing_samples-samples"));session$setInputs(preprocessing_threads=2,mapfastq_dry_run=FALSE,mapfastq_force=FALSE,mapfastq_keep_going=TRUE);session$flushReact();stopifnot(identical(preprocessing_selected_samples(),sample));session$setInputs(run_mapfastq=1);session$flushReact();stopifnot(jobs$job_is_running());deadline<-Sys.time()+300;while(jobs$job_is_running()&&Sys.time()<deadline){jobs$poll_job();p<-jobs$current_progress();if(!is.null(p)){observed$running<-observed$running||p$status%in%c("queued","starting","running");observed$current<-observed$current||identical(p$current_item,sample)};observed$logs<-observed$logs||length(jobs$current_stdout())>0||length(jobs$current_stderr())>0;Sys.sleep(.1)};jobs$poll_job();p<-jobs$current_progress();stopifnot(!jobs$job_is_running(),observed$running,observed$current,p$status=="success",p$successful_items==1,p$skipped_items==0,p$failed_items==0,p$remaining_items==0,state$values$view=="workspace");observed$logs<-observed$logs||length(jobs$current_stdout())>0;stopifnot(observed$logs);cat(sprintf("Elapsed seconds: %.3f\nProgress file: %s\n",p$job_elapsed_seconds,jobs$current_job()$progress_file))})
stopifnot(file.exists(bam),file.exists(bai),file.exists(stats));cat("BAM:",bam,"\nBAI:",bai,"\nStats:",stats,"\nPASS\n")
